public long readRawVarint64() throws IOException {
    // Read the first byte of the Varint
    int firstByte = inputStream.read();

    // If the first byte is equal to -1, throw an EOFException
    if (firstByte == -1) {
        throw new EOFException("Input stream ended unexpectedly");
    }

    // The first byte is in the range [0, 127): it can be the only byte of the Varint
    if (firstByte <= 127) {
        return firstByte;
    }

    // The first byte is in the range [128, 191): it is the first byte of a two-byte Varint
    if (firstByte >= 193 && firstByte <= 255) {
        // Read the second byte
        int secondByte = inputStream.read();

        // If the second byte is equal to -1, throw an EOFException
        if (secondByte == -1) {
            throw new EOFException("Input stream ended unexpectedly");
        }

        // Return the Varint value
        return (firstByte - 128) * 256 + secondByte;
    }

    // The first byte is in the range [224, 255): it is the first byte of a four-byte Varint
    if (firstByte >= 224 && firstByte <= 255) {
        // Read the three following bytes
        int[] bytes = new int[3];
        for (int i = 1; i < bytes.length; i++) {
            bytes[i] = inputStream.read();

            // If a byte is equal to -1, throw an EOFException
            if (bytes[i] == -1) {
                throw new EOFException("Input stream ended unexpectedly");
            }
        }

        // Return the Varint value
        long value = 0;
        for (int i = 0; i < bytes.length; i++) {
            value += bytes[i] * Math.pow(256, i);
        }
        return value;
    }

