private void pop(final String descriptor) {
    // Check if descriptor is a type descriptor
    if (Type.getObjectType(descriptor).getSort() != Type.ARRAY && Type.getObjectType(descriptor).getSort() != Type.OBJECT) {
        // Pop the descriptor from the output frame stack
        stack.pop(Integer.parseInt(descriptor), false);
    } else {
        // Pop the argument types of the method from the output frame stack
        for (Type argType : Type.getArgumentTypes(descriptor)) {
            stack.pop(Integer.parseInt(argType.getDescriptor()), false);
        }
    }
}
