private static boolean isPrime(int n) {
    if (n <= 4) {
        return n > 1;
    } else if (n % 2 == 0) {
        return false;
    }
    for (int i = 3, max = (int)Math.sqrt(n); i <= max; i += 2) {
        if (n % i == 0) {
            return false;
        }
    }
    return true;
