public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {

    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();

    // Read the file line by line
    List<String> lines = Files.readAllLines(file.toPath());

    // Start iterating through each line
    for (String line : lines) {
        // Check if the line matches the time range
        for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
            if (line.contains(timeRange.getStartTime() + "-" + timeRange.getEndTime())) {
                // Extract the thread name and the thread ID from the line
                String[] lineSplit = line.split("\\s+");
                String threadName = lineSplit[2];
                String threadId = lineSplit[3];

                // Create a new ThreadSnapshot object for this line
                ThreadSnapshot threadSnapshot = new ThreadSnapshot(threadName, threadId);

                // Add it to the list of thread snapshots
                threadSnapshots.add(threadSnapshot);
            }
        }
    }

    return threadSnapshots;
}
